  final inboxTimer = _startInboxWatcher();
  try {
    if (_useTui) {
      // The TUI prints the banner itself into its output history (buffered
      // by the controller until the program's event loop is listening).
      await _runTuiRepl();
    } else {
      await _runLineRepl();
    }
